#!/usr/bin/env python3
"""Turns tools/stations.json into the Kotlin and JavaScript station tables.

Keeping one JSON file means the app and the preview cannot disagree about which
station sits where on the dial.

    python3 tools/gen_stations.py
"""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
data = json.loads((ROOT / "tools" / "stations.json").read_text(encoding="utf-8"))
stations = data["stations"]

# --- Kotlin ----------------------------------------------------------------
kt = [
    "// GENERATED by tools/gen_stations.py from tools/stations.json.",
    "// Do not edit by hand: change the JSON and re-run the generator.",
    "package com.dumbos.apps.radio",
    "",
    "/** A station in the dumbOS catalogue. */",
    "data class Station(",
    "    val key: String,",
    "    val name: String,",
    "    val desc: String,",
    "    /** Dial position, so the analogue tuning metaphor still holds. */",
    "    val freq: Float,",
    "    val format: String,",
    "    val url: String,",
    ")",
    "",
    "object Stations {",
    "    val ALL: List<Station> = listOf(",
]
for s in stations:
    kt.append(
        '        Station("%s", "%s", "%s", %.1ff, "%s",\n'
        '            "%s"),'
        % (s["key"], s["name"], s["desc"], s["freq"], s["fmt"], s["url"])
    )
kt += [
    "    )",
    "",
    "    /** Nearest station to a dial position, or null when nothing is close. */",
    "    fun nearest(freq: Float, tolerance: Float = 0.45f): Station? =",
    "        ALL.minByOrNull { kotlin.math.abs(it.freq - freq) }",
    "            ?.takeIf { kotlin.math.abs(it.freq - freq) < tolerance }",
    "",
    "    fun byKey(key: String): Station? = ALL.firstOrNull { it.key == key }",
    "}",
    "",
]
kt_path = ROOT / "app/src/main/java/com/dumbos/apps/radio/Stations.kt"
kt_path.write_text("\n".join(kt), encoding="utf-8")

# --- JavaScript ------------------------------------------------------------
js = [
    "// GENERATED by tools/gen_stations.py from tools/stations.json.",
    "// Do not edit by hand: change the JSON and re-run the generator.",
    "const STATIONS = [",
]
for s in stations:
    js.append(
        "  { key: '%s', name: '%s', desc: '%s', freq: %.1f, fmt: '%s',\n"
        "    url: '%s' },"
        % (s["key"], s["name"], s["desc"], s["freq"], s["fmt"], s["url"])
    )
js += [
    "];",
    "",
    "function stationNearest(freq, tol = 0.45) {",
    "  let best = null, bestD = Infinity;",
    "  for (const s of STATIONS) {",
    "    const d = Math.abs(s.freq - freq);",
    "    if (d < bestD) { bestD = d; best = s; }",
    "  }",
    "  return bestD < tol ? best : null;",
    "}",
    "",
]
js_path = ROOT / "web/stations.js"
js_path.write_text("\n".join(js), encoding="utf-8")

print("wrote %d stations -> %s and %s" % (len(stations), kt_path.name, js_path.name))
